import {hearButton} from './play-media.mjs';
import {circuitCases,circuitLinks} from './lantern-circuit-content.mjs';
import {circuitView,circuitStatus,startCircuit,setCircuitPage,setCircuitLink,keepCircuit,recoverCircuits} from './lantern-circuit-core.mjs';
import {circuitDrawing,circuitModelLabel} from './lantern-circuit-art.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,attrs,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const pages={learn:'Learn',connect:'Connect',kept:'Kept'};
const wireText=s=>circuitLinks.filter(l=>s.mask&l.bit).map(l=>`${l.tag} (${l.ends}): ${s.source.copy.wireLabels[l.key]}`).join('; ')||'No external wires installed';
const statusText=s=>{const k=circuitStatus(s.mask),c=s.source.copy.status[k];return `${circuitModelLabel(s.mask)}. ${c.title}. ${c.text}`;};
const statusHTML=s=>{const k=circuitStatus(s.mask),c=s.source.copy.status[k];return `<div class="lc-model-status" data-lc-status="${k}" role="status"><strong>${esc(circuitModelLabel(s.mask))}</strong><p>${esc(c.title)}</p><p>${esc(c.text)}</p></div>`;};
const reference=s=>`<aside class="lc-reference"><p>${esc(s.copy.reference)}</p><p><strong>${esc(s.request)}</strong></p></aside>`;
const legend=()=>'<details class="lc-legend"><summary>Read the cutaway labels</summary><p>P: cell +. N: cell −. S: bulb metal side. T: bulb tip.</p><p>The globe is the bulb. The brown internal zigzag and its leads show the filament path. The pale insulating band separates the metal side and solid metal tip.</p><p>W1–W4 are connecting wires, not the filament. A raised bridge means the crossing wires do not join. Only P, N, S and T are junctions.</p></details>';
const list=s=>`<p class="lc-wire-list"><strong>Installed wires:</strong> ${esc(wireText(s))}.</p>`;
function shown(v,step){const w=v.work;return w.page==='learn'?{source:w.source,mask:w.source.example.frames[step].mask}:w.page==='kept'?v.kept||null:w;}
function narration(v,step=0){if(!v.work)return 'Choose any lantern. Every table is open.';const w=v.work,s=shown(v,step);if(!s)return v.keptUnreadable?'An earlier unreadable kept version stays in the download.':'Nothing kept yet. Open Connect to keep an unfinished or finished arrangement.';return `${s.source.copy.reference} ${s.source.request} ${w.page==='learn'?s.source.copy.idea+' '+s.source.copy.contacts+' '+s.source.example.frames[step].caption+' ':w.page==='kept'?'Our kept version. ':''}${wireText(s)}. ${statusText(s)} ${s.source.copy.limit}`;}
function figure(s,highlight=false){return `<figure class="lc-figure">${circuitDrawing(s.mask,highlight)}<figcaption>${esc(circuitModelLabel(s.mask))}</figcaption></figure>`;}
function chooser(v){return `<details class="lc-chooser" ${v.work?'':'open'}><summary>Choose any lantern</summary>${circuitCases.map(s=>{const c=v.readable.find(x=>x.id===s.id),bad=v.unreadable.some(x=>x.id===s.id);return `<article><h3>${esc(c?.work.source.title||s.title)}</h3>${bad?'<p>Earlier unreadable work stays in your download; the other lanterns remain open.</p>':btn(c?'Resume this lantern':'Start this lantern',`data-lc-start="${s.id}"`)}</article>`;}).join('')}${v.readable.filter(c=>!circuitCases.some(s=>s.id===c.id)).map(c=>`<article><h3>${esc(c.work.source.title)}</h3>${btn('Resume earlier lantern',`data-lc-start="${esc(c.id)}"`)}</article>`).join('')}</details>`;}
export function circuitPage(state){
 const v=circuitView(state),head='<section class="lc-sheet" data-lc-root><a class="back" href="#workshop">Back to Storm Workshop</a><p class="lc-switch-entry"><a class="secondary" href="#workshop/switch-table">Try the Switch Table · open and close a path</a> <a class="secondary" href="#mill/energy">Where does the energy come from?</a></p>',status='<p id="lc-status" role="status" tabindex="-1"></p>';
 if(v.status==='recovery')return head+'<h1 id="lc-title" tabindex="-1">Earlier lantern work is kept</h1><p>This notebook cannot be opened here. The original remains in your download.</p>'+btn('Start a separate lantern notebook','data-lc-recover')+status+'<a class="secondary" href="#notes">Download notes</a></section>';
 if(!v.work)return head+'<h1 id="lc-title" tabindex="-1">Lantern Circuit Bench</h1><p>Moss is preparing a pretend electric lantern for the town’s show. Explore a path through a filament bulb.</p>'+chooser(v)+status+'<a class="secondary" href="#notes">Download notes</a>'+(v.unreadable.length?btn('Start a separate lantern notebook','data-lc-recover'):'')+'</section>';
 const w=v.work,s=w.source,display=shown(v,0);let body='';
 if(w.page==='learn')body=`<p>${esc(s.copy.idea)}</p><p>${esc(s.copy.contacts)}</p><div class="lc-example"><h2>A supplied example</h2><div data-lc-example>${figure(display)}<p data-lc-caption>${esc(s.example.frames[0].caption)}</p>${statusHTML(display)}</div><div class="lc-actions">${[0,1,2].map(i=>btn('Example picture '+(i+1),`data-lc-example-step="${i}" aria-pressed="${i===0}"`)).join('')}</div></div>${btn('Try our connections','data-lc-page="connect"',true)}`;
 if(w.page==='connect')body=`<p>Add or remove one connection. Notice the path, then change it back.</p><div data-lc-board>${figure(w)}</div><div class="lc-links" role="group" aria-label="Four external connections">${circuitLinks.map(l=>btn(`${w.mask&l.bit?'Remove':'Add'}: ${s.copy.wireLabels[l.key]}`,`data-lc-link="${l.key}" data-lc-value="${!(w.mask&l.bit)}" aria-pressed="${!!(w.mask&l.bit)}"`)).join('')}</div>${list(w)}${statusHTML(w)}${btn(w.kept===null?'Keep this version':'Replace our kept version',`data-lc-keep ${v.keptUnreadable?'disabled':''}`,true)}${v.keptUnreadable?'<p>An unreadable kept copy is retained. Use a separate lantern notebook to keep another version.</p>':''}`;
 if(w.page==='kept')body=v.kept?`<h2>Our kept arrangement</h2><div data-lc-board>${figure(v.kept)}</div>${list(v.kept)}${statusHTML(v.kept)}<p>This copy stays unchanged while you try other connections.</p>${btn('Return to our connections','data-lc-page="connect"')}`:v.keptUnreadable?'<p>The earlier kept version is unreadable and stays unchanged in your download. Other work remains open.</p>':'<p>Nothing kept yet. Open Connect to keep any arrangement, including an unfinished or paused one.</p>';
 const source=display?.source||s;
 return head+`<h1 id="lc-title" tabindex="-1">Lantern Circuit Bench</h1>${reference(source)}<nav class="lc-actions" aria-label="Lantern turns">${Object.entries(pages).map(([k,label])=>btn(label,`data-lc-page="${k}" aria-current="${w.page===k?'page':'false'}"`)).join('')}</nav>${hearButton(narration(v),'Hear this turn').replace('<button ','<button data-lc-hear ')}${status}${body}<p class="lc-limit">${esc(source.copy.limit)}</p>${display?`<details class="lc-loop"><summary>Show the loop</summary><div data-lc-loop><p>${esc(display.source.copy.loop[circuitStatus(display.mask)])}</p>${hearButton(display.source.copy.loop[circuitStatus(display.mask)],'Hear the path')}</div></details>`:''}<details class="lc-extras"><summary>Labels, Help and other lanterns</summary>${legend()}<p class="lc-wire-key">${circuitLinks.map(l=>`${l.tag} (${l.ends}): ${esc(source.copy.wireLabels[l.key])}`).join(' · ')}</p><details class="lc-help"><summary>Help with the connections</summary><p>${esc(source.copy.help)}</p>${hearButton(source.copy.help,'Hear this explanation')}</details><p>${esc(source.copy.talk)}</p>${chooser(v)}<details><summary>For grown-ups: model and recovery</summary><p>This is an unscored screen model. A saved arrangement is not evidence of physical circuit-building or independent understanding. Notes retain its own wording and raw work.</p><a class="secondary" href="#notes">Download notes</a>${btn('Start a separate lantern notebook','data-lc-recover')}</details></details></section>`;
}
export function circuitNotes(state){const v=circuitView(state);if(v.status==='missing')return '';if(v.status==='recovery')return '<section><h2>Lantern Circuit Bench</h2><p>Earlier unreadable notebook remains raw in this download.</p></section>';return `<details class="panel"><summary>Lantern Circuit Bench (${v.readable.length} lanterns)</summary><p>Unscored saved screen-model arrangements. No physical result, independent explanation or mastery inferred.</p>${v.readable.map(c=>`<section><h3>${esc(c.work.source.title)}</h3><p>Current: ${esc(wireText(c.work))}. ${esc(statusText(c.work))}</p><p>${esc(c.work.source.copy.limit)}</p>${c.kept?`<p>Kept: ${esc(wireText(c.kept))}. ${esc(statusText(c.kept))}</p>`:''}${c.keptUnreadable?'<p>Unreadable kept version retained raw.</p>':''}</section>`).join('')}${v.unreadable.length?'<p>Unreadable cases remain in the download; readable cases stay open.</p>':''}</details>`;}
export function bindCircuits(state,{save,render,focus,canExport,explorerId=()=>null}){
 const scope=document.querySelector('[data-lc-root]');if(!scope)return;
 const bound=state.lanternCircuits,explorer=explorerId(),current=circuitView(state).root?.current??null;
 const live=b=>location.hash==='#workshop/lantern'&&scope.isConnected&&b.isConnected&&scope.contains(b)&&state.lanternCircuits===bound&&(circuitView(state).root?.current??null)===current&&explorerId()===explorer;
 const message=text=>{const n=scope.querySelector('#lc-status');n.textContent=text;focus('#lc-status');};
 const run=(fn,target='#lc-title')=>{if(!live(scope))return false;if(!fn()){message('This change could not fit safely. Earlier work stays unchanged. Download notes, or use a separate explorer if the notebook is full.');return false;}save();render();focus(target);return true;};
 const bind=(sel,fn)=>scope.querySelectorAll(sel).forEach(b=>b.addEventListener('click',e=>{if(live(b))fn(b,e);else e.stopImmediatePropagation();}));
 function confirm(recovery,fn){const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-content"><h2>${recovery?'Start a separate lantern notebook?':'Replace our kept version?'}</h2><p>${recovery?'The entire earlier lantern notebook, including raw and kept work, stays in your download.':'This overwrites the one earlier kept version for this lantern.'} Download notes first if you want another copy.</p><button class="secondary" data-lc-cancel>Keep this page</button><button class="primary" data-lc-confirm>Yes, continue</button></div>`;document.body.append(d);d.showModal();d.querySelector('[data-lc-cancel]').onclick=()=>d.close();d.querySelector('[data-lc-confirm]').onclick=()=>{if(!d.isConnected||!d.open||!live(scope))return;d.close();run(fn);};d.addEventListener('close',()=>d.remove());}
 bind('[data-lc-start]',b=>run(()=>startCircuit(state,b.dataset.lcStart,canExport)));
 bind('[data-lc-page]',b=>run(()=>setCircuitPage(state,b.dataset.lcPage,canExport)));
 bind('[data-lc-link]',b=>run(()=>setCircuitLink(state,b.dataset.lcLink,b.dataset.lcValue==='true',canExport),`[data-lc-link="${b.dataset.lcLink}"]`));
 bind('[data-lc-keep]',()=>{const v=circuitView(state);if(v.keptUnreadable)return;if(v.work.kept!==null)confirm(false,()=>keepCircuit(state,true,canExport));else if(run(()=>keepCircuit(state,false,canExport),'#lc-status')){const n=document.querySelector('#lc-status');n.textContent='This version is kept. Open Kept to revisit it.';focus('#lc-status');}});
 bind('[data-lc-recover]',()=>confirm(true,()=>recoverCircuits(state,canExport)));
 let step=0;
 const updateLoop=()=>{const v=circuitView(state),s=shown(v,step),loop=scope.querySelector('.lc-loop');if(!loop||!s)return;const t=s.source.copy.loop[circuitStatus(s.mask)],container=scope.querySelector('[data-lc-loop]');container.querySelector('p').textContent=t;container.querySelector('[data-speak]').dataset.speak=t;const holder=scope.querySelector(v.work.page==='learn'?'[data-lc-example]':'[data-lc-board]');if(holder)holder.querySelector('svg').classList.toggle('lc-highlight',loop.open&&circuitStatus(s.mask)==='glow');};
 bind('[data-lc-example-step]',b=>{step=Number(b.dataset.lcExampleStep);const v=circuitView(state),s=shown(v,step),e=scope.querySelector('[data-lc-example]');e.innerHTML=figure(s)+`<p data-lc-caption>${esc(s.source.example.frames[step].caption)}</p>`+statusHTML(s);scope.querySelectorAll('[data-lc-example-step]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));updateLoop();});
 scope.querySelector('.lc-loop')?.addEventListener('toggle',e=>{if(live(e.target))updateLoop();});
 scope.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live(b)){e.stopImmediatePropagation();return;}if(b.hasAttribute('data-lc-hear'))b.dataset.speak=narration(circuitView(state),step);}));
}
